cd /app && \
# Add the singular /search resource near other top-level content indexes.
sed -i '/  resources :tags, only: :index/a\  resource :search, only: :show' config/routes.rb && \
# Add search behavior as a focused Card concern.
cat > app/models/card/searchable.rb <<'RUBY'
module Card::Searchable
  extend ActiveSupport::Concern

  included do
    scope :matching, ->(query) do
      if query.present?
        pattern = "%#{sanitize_sql_like(query.downcase)}%"

        where(<<~SQL.squish, pattern: pattern)
          LOWER(cards.title) LIKE :pattern
          OR EXISTS (
            SELECT 1
            FROM action_text_rich_texts descriptions
            WHERE descriptions.record_type = 'Card'
              AND descriptions.record_id = cards.id
              AND descriptions.name = 'description'
              AND LOWER(descriptions.body) LIKE :pattern
          )
          OR EXISTS (
            SELECT 1
            FROM comments
            INNER JOIN action_text_rich_texts comment_bodies
              ON comment_bodies.record_type = 'Comment'
              AND comment_bodies.record_id = comments.id
              AND comment_bodies.name = 'body'
            WHERE comments.card_id = cards.id
              AND LOWER(comment_bodies.body) LIKE :pattern
          )
        SQL
      else
        none
      end
    end
  end
end
RUBY
# Include the concern in Card.
ruby -e 'p = "app/models/card.rb"; s = File.read(p); s.sub!("Readable, Stallable, Statuses, Storage::Tracked", "Readable, Searchable, Stallable, Statuses, Storage::Tracked"); File.write(p, s)' && \
# Add the endpoint.
cat > app/controllers/searches_controller.rb <<'RUBY'
class SearchesController < ApplicationController
  def show
    @query = params[:q].to_s.strip
    @cards = Current.user.accessible_cards.published.matching(@query).reverse_chronologically
      .preload(:board, :rich_text_description, comments: :rich_text_body)
  end
end
RUBY
# Add safe, presentation-only matching/highlighting helpers.
cat > app/helpers/searches_helper.rb <<'RUBY'
module SearchesHelper
  def search_highlight(text, query)
    highlight(text.to_s, query, highlighter: "<mark>\\1</mark>")
  end

  def search_match?(text, query)
    text.to_s.downcase.include? query.downcase
  end
end
RUBY
# Add result and page views.
mkdir -p app/views/searches && cat > app/views/searches/_card.html.erb <<'ERB'
<%= tag.article class: "search-result", data: { card_id: card.id } do %>
  <header class="search-result__header flex align-baseline justify-space-between gap">
    <h2 class="txt-large margin-none">
      <%= link_to search_highlight(card.title, query), card_path(card), class: "search-result__title" %>
    </h2>
    <span class="txt-small txt-ink-muted txt-nowrap"><%= card.board.name %></span>
  </header>

  <% if search_match?(card.description.to_plain_text, query) %>
    <p class="search-result__match"><%= search_highlight(card.description.to_plain_text, query) %></p>
  <% end %>

  <% card.comments.each do |comment| %>
    <% if search_match?(comment.body.to_plain_text, query) %>
      <blockquote class="search-result__match search-result__comment">
        <%= search_highlight(comment.body.to_plain_text, query) %>
      </blockquote>
    <% end %>
  <% end %>
<% end %>
ERB
cat > app/views/searches/show.html.erb <<'ERB'
<% @page_title = "Search" %>

<% content_for :header do %>
  <div class="header__actions header__actions--start">
    <%= back_link_to "Home", root_path, "keydown.left@document->hotkey#click keydown.esc@document->hotkey#click" %>
  </div>

  <h1 class="header__title" data-bridge--title-target="header"><%= @page_title %></h1>
<% end %>

<section class="search panel panel--wide borderless center margin">
  <%= form_with url: search_path, method: :get, class: "search__form flex gap-half", data: { turbo_action: "replace" } do |form| %>
    <%= form.search_field :q, value: @query, class: "input", placeholder: "Search cards…", autofocus: true,
          autocorrect: "off", autocomplete: "off", aria: { label: "Search cards" }, data: { "1p-ignore": "true" } %>
    <%= form.submit "Search", class: "btn btn--link" %>
  <% end %>

  <% if @query.blank? %>
    <p class="search__blank txt-align-center txt-ink-muted">Search card titles, descriptions, and comments.</p>
  <% elsif @cards.any? %>
    <div class="search-results">
      <%= render partial: "card", collection: @cards, locals: { query: @query } %>
    </div>
  <% else %>
    <p class="search__blank blank-slate txt-align-center">No cards match “<%= @query %>”</p>
  <% end %>
</section>
ERB
