sed -i '/collapsible_nav_section "Shortcuts"/a\  <%= filter_place_menu_item search_path, "Search cards", "search" %>' app/views/my/menus/_shortcuts.html.erb && \
# Add compact page-specific styling.
cat > app/assets/stylesheets/searches.css <<'CSS'
@layer components {
  .search {
    display: grid;
